import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

const root = fileURLToPath(new URL("../../../../../", import.meta.url));
function scenario(body: string) {
  const source = String.raw`
    import assert from "node:assert/strict";
    import { receipt, diagnostics } from "./scripts/automation-receipt.mjs";
    import { collectDiagnostics, reportCompletedRun, reportOutcome, GitHub } from "./scripts/automation-report.mjs";
    import { publishRun, recoverRun } from "./scripts/automation-publish.mjs";
    const A = "a".repeat(40), B = "b".repeat(40), C = "c".repeat(40);
    const repository = "chahyasantoso/motion5";
    const run = {id: 42, run_attempt: 1, workflow_id: 7, head_sha: B, head_branch: "test/diagnostics", event: "push", path: ".github/workflows/ai-edit.yml", status: "completed", conclusion: "failure", repository: {full_name: repository}, head_repository: {full_name: repository}};
    const value = receipt({kind: "ai-edit", repository, run_id: 42, run_attempt: 1, request_commit: B, phase: "selection"});
    const saved = new Map(), comments = [], writes = [];
    let logCalls = 0, currentHead = B, failComment = false;
    const missing = () => {const error = new Error("missing"); error.status = 404; throw error;};
    const api = {
      repository,
      head: async () => A,
      content: async (path) => {
        if (path === run.path) return {sha: A};
        if (!saved.has(path)) return missing();
        return {text: saved.get(path)};
      },
      failedLogs: async (input) => {logCalls++; assert.equal(input.id, run.id); assert.equal(input.run_attempt, run.run_attempt); return "setup output\nError: Stale source SHA\n<script>@everyone</script> token=fixture-sensitive";},
      persist: async (files) => {
        writes.push(files);
        for (const [path, text] of Object.entries(files)) {assert.ok(!saved.has(path) || saved.get(path) === text, "historical evidence changed"); saved.set(path, text);}
      },
      list: async (path) => {
        if (path.startsWith("/commits/")) return [{number: 9, state: "open", base: {repo: {full_name: repository}}, head: {repo: {full_name: repository}, ref: run.head_branch}}];
        if (path === "/issues/9/comments") return comments;
        assert.fail("unexpected list " + path);
      },
      request: async (method, path, data) => {
        if (method === "GET" && path === "/pulls/9") return {state: "open", head: {repo: {full_name: repository}, ref: run.head_branch, sha: currentHead}};
        if (["POST", "PATCH"].includes(method) && path.startsWith("/issues/")) {
          if (failComment) return missing();
          const comment = {id: 8, user: {id: 41898282, type: "Bot"}, body: data.body};
          if (comments.length) comments[0] = comment; else comments.push(comment);
          return;
        }
        assert.fail("unexpected request " + method + " " + path);
      },
    };
    const writer = {request: async () => assert.fail("failure/recovery must never publish a candidate")};
    const detailPath = () => "receipts/ai-edit/" + run.id + "/" + run.run_attempt + "/diagnostics.json";
  `;
  const result = spawnSync(process.execPath, ["--input-type=module", "-e", source + body], {cwd: root, encoding: "utf8", timeout: 10000, maxBuffer: 1000000});
  expect(result.status, result.stderr).toBe(0);
}

describe("complete failure reporting without publication replay", () => {
  it.each(["failure", "cancelled", "timed_out", "skipped"])("retains and projects %s preparation evidence", (conclusion) => {
    scenario("run.conclusion = " + JSON.stringify(conclusion) + ";" + String.raw`
      await publishRun(api, writer, run, A);
      assert.equal(logCalls, 1, "AI failure bypassed diagnostic collection");
      const detail = JSON.parse(saved.get(detailPath()));
      assert.equal(detail.run_conclusion, run.conclusion);
      assert.equal(detail.state, "available");
      assert.ok(detail.excerpt.includes("Stale source SHA"));
      assert.ok(comments[0].body.includes("Preparation: **" + run.conclusion + "**"));
      assert.ok(comments[0].body.includes("Stale source SHA") && comments[0].body.includes("diagnostics.json"));
      assert.ok(!comments[0].body.includes("<script>") && !comments[0].body.includes("@everyone"));
      assert.ok(![...saved.values()].join("").includes("fixture-sensitive"));
      assert.ok(!comments[0].body.includes("inspect operation.json"), "failed preparation links nonexistent operation output");
      assert.equal(JSON.parse(saved.get(value.evidence_path)).publication, "not_attempted");
    `);
  });
  it("prefers a plain Error reason beyond setup noise", () => {
    scenario(String.raw`
      const detail = await collectDiagnostics(async () => "setup \

\nError: Stale source SHA\n");
      assert.ok(detail.excerpt.includes("Stale source SHA"), "plain error lost behind log prefix");
    `);
  });
  it("retries unavailable logs and preserves unavailable evidence on recovery", () => {
    scenario(String.raw`
      api.failedLogs = async () => {logCalls++; throw new Error("transport secret=hidden");};
      await publishRun(api, writer, run, A);
      assert.equal(logCalls, 3);
      const bytes = saved.get(detailPath());
      assert.equal(JSON.parse(bytes).state, "unavailable");
      api.failedLogs = async () => assert.fail("recovery refetched immutable diagnostics");
      await recoverRun(api, run, A);
      assert.equal(saved.get(detailPath()), bytes);
      assert.ok(comments[0].body.includes("unavailable"));
    `);
  });
  it("restores diagnostic detail after comment failure without rewriting evidence", () => {
    scenario(String.raw`
      failComment = true;
      await assert.rejects(publishRun(api, writer, run, A), /missing/);
      assert.ok(saved.has(detailPath()), "diagnostics were not durable before comment failure");
      const before = new Map(saved); failComment = false;
      api.failedLogs = async () => assert.fail("recovery must reuse retained diagnostics");
      await recoverRun(api, run, A);
      assert.deepEqual(saved, before);
      assert.ok(comments[0].body.includes("Stale source SHA"));
    `);
  });
  it("independent recovery collects failure evidence before any primary report", () => {
    scenario(String.raw`
      await recoverRun(api, run, A);
      assert.ok(saved.has(detailPath()), "independent fallback omitted failure reason");
      assert.ok(comments[0].body.includes("Stale source SHA"));
    `);
  });
  it("adds missing diagnostics beside a legacy receipt without changing its bytes", () => {
    scenario(String.raw`
      const bytes = JSON.stringify(value) + "\n"; saved.set(value.evidence_path, bytes);
      await publishRun(api, writer, run, A);
      assert.equal(saved.get(value.evidence_path), bytes);
      assert.ok(saved.has(detailPath()), "legacy receipt blocked diagnostic completion");
    `);
  });
  it("does not swallow a 404 while replaying an existing confirmed receipt", () => {
    scenario(String.raw`
      run.conclusion = "success"; currentHead = C; failComment = true;
      const confirmed = receipt({kind: "ai-edit", repository, run_id: 42, run_attempt: 1, request_commit: B, source_sha: A, request_digest: "d".repeat(64), phase: "publication", candidate_sha: C, published_sha: C});
      saved.set(confirmed.evidence_path, JSON.stringify(confirmed) + "\n");
      await assert.rejects(publishRun(api, writer, run, A), /missing/);
    `);
  });
  it("retains stale completion evidence without changing the visible summary", () => {
    scenario(String.raw`
      currentHead = C;
      assert.equal((await publishRun(api, writer, run, A)).comment, "stale");
      assert.ok(saved.has(detailPath())); assert.equal(comments.length, 0);
    `);
  });
  it("keeps attempts independent and refuses an older same-head projection", () => {
    scenario(String.raw`
      run.run_attempt = 2; await publishRun(api, writer, run, A);
      const body = comments[0].body; run.run_attempt = 1;
      assert.equal((await publishRun(api, writer, run, A)).comment, "stale");
      assert.equal(comments[0].body, body);
      assert.ok(saved.has(detailPath()) && saved.has("receipts/ai-edit/42/2/diagnostics.json"));
    `);
  });
  it("propagates evidence persistence failures before commenting", () => {
    scenario(String.raw`
      api.persist = async () => {throw new Error("evidence write failed");};
      await assert.rejects(publishRun(api, writer, run, A), /evidence write failed/);
      assert.equal(comments.length, 0);
    `);
  });
  it("rejects conflicting retained preparation conclusions", () => {
    scenario(String.raw`
      saved.set(detailPath(), JSON.stringify({state: "available", excerpt: "unrelated", run_conclusion: "success", paths: []}));
      await assert.rejects(publishRun(api, writer, run, A), /conclusion/);
      assert.equal(comments.length, 0);
    `);
  });
  it("fills missing CI diagnostics even when its receipt already exists", () => {
    scenario(String.raw`
      run.path = ".github/workflows/ci.yml";
      const ci = receipt({kind: "ci", repository, run_id: 42, run_attempt: 1, head_sha: B, tested_sha: B, ci: "failure"});
      const bytes = JSON.stringify(ci) + "\n"; saved.set(ci.evidence_path, bytes);
      await reportCompletedRun(api, run, A);
      assert.equal(saved.get(ci.evidence_path), bytes);
      assert.ok(saved.has("receipts/ci/42/1/diagnostics.json"), "existing CI receipt prevented diagnostic completion");
      assert.ok(comments[0].body.includes("Stale source SHA"));
    `);
  });
  it("validates run identity before invoking the concrete log adapter", () => {
    scenario(String.raw`
      const concrete = new GitHub(repository, "fixture-only");
      assert.equal(typeof concrete.failedLogs, "function");
      await assert.rejects(concrete.failedLogs({...run, repository: {full_name: "other/repo"}}), /Repository mismatch/);
    `);
  });
});
